/*
 * Host program for the static git2html binary. Embeds a Lua 5.4 interpreter,
 * lpeg (statically linked), and every Lua source file git2html needs
 * (build/bundle_data.c, generated by tools/gen_bundle.lua) into a single
 * executable with no run-time dependency on the system's Lua install or any
 * sibling files on disk.
 */
#include <stdio.h>
#include <string.h>

#include "lua.h"
#include "lauxlib.h"
#include "lualib.h"

#include "bundle_data.h"

int luaopen_lpeg(lua_State *L);

/*
 * vendor/syntaxhighlight's per-language lexer loader (init.lua, and
 * textadept/lexer.lua's M.load) doesn't use require() -- it reconstructs a
 * filesystem path from package.path and calls loadfile()/dofile() on it
 * directly, because it's designed to also run outside a full Lua
 * installation (e.g. embedded in an editor). There are no real files for it
 * to find here, so this redirects any loadfile/dofile call whose path looks
 * like ".../syntaxhighlight/lexers/<name>.lua" or
 * ".../syntaxhighlight/textadept/<name>.lua" to the matching entry already
 * registered in package.preload, and only falls through to the real
 * loadfile/dofile otherwise.
 */
static const char *const LEXER_SHIM = ""
    "local real_loadfile = loadfile\n"
    "local preload = package.preload\n"
    "local function resolve(filename)\n"
    "    if not filename then return nil end\n"
    "    local name = filename:match('syntaxhighlight/lexers/([%w_]+)%.lua$')\n"
    "    if name then return 'syntaxhighlight.lexers.' .. name end\n"
    "    name = filename:match('syntaxhighlight/textadept/([%w_]+)%.lua$')\n"
    "    if name then return 'syntaxhighlight.textadept.' .. name end\n"
    "    return nil\n"
    "end\n"
    "loadfile = function(filename, ...)\n"
    "    local mod = resolve(filename)\n"
    "    if mod and preload[mod] then return preload[mod] end\n"
    "    return real_loadfile(filename, ...)\n"
    "end\n"
    "dofile = function(filename)\n"
    "    local mod = resolve(filename)\n"
    "    if mod and preload[mod] then return preload[mod]() end\n"
    "    return assert(real_loadfile(filename))()\n"
    "end\n";

static int report(lua_State *L, int status) {
    if (status != LUA_OK) {
        fprintf(stderr, "git2html: %s\n", lua_tostring(L, -1));
        lua_pop(L, 1);
    }
    return status;
}

int main(int argc, char **argv) {
    lua_State *L = luaL_newstate();
    if (!L) {
        fprintf(stderr, "git2html: out of memory initializing Lua\n");
        return 1;
    }
    luaL_openlibs(L);

    luaL_requiref(L, "lpeg", luaopen_lpeg, 0);
    lua_pop(L, 1);

    /* Preload every bundled module so require() finds it without touching
     * the filesystem. */
    lua_getglobal(L, "package");
    lua_getfield(L, -1, "preload");
    for (size_t i = 0; i < g2h_modules_count; i++) {
        if (luaL_loadbuffer(L, (const char *)g2h_modules[i].data,
                             g2h_modules[i].len, g2h_modules[i].name) != LUA_OK) {
            fprintf(stderr, "git2html: bundled module %s: %s\n",
                    g2h_modules[i].name, lua_tostring(L, -1));
            return 1;
        }
        lua_setfield(L, -2, g2h_modules[i].name);
    }
    lua_pop(L, 2); /* preload, package */

    /* Expose the bundled theme CSS to git2html.lua's theme selection. */
    lua_newtable(L);
    for (size_t i = 0; i < g2h_themes_count; i++) {
        lua_pushlstring(L, (const char *)g2h_themes[i].data, g2h_themes[i].len);
        lua_setfield(L, -2, g2h_themes[i].name);
    }
    lua_setglobal(L, "_EMBEDDED_THEMES");

    if (report(L, luaL_dostring(L, LEXER_SHIM)) != LUA_OK) {
        return 1;
    }

    /* luaL_loadbuffer, unlike luaL_loadfile, has no shebang-skipping logic,
     * so drop git2html.lua's leading "#!/usr/bin/env lua" line ourselves. */
    const char *main_src = (const char *)g2h_main;
    size_t main_len = g2h_main_len;
    if (main_len > 0 && main_src[0] == '#') {
        const char *nl = memchr(main_src, '\n', main_len);
        if (nl) {
            main_len -= (size_t)(nl + 1 - main_src);
            main_src = nl + 1;
        }
    }
    if (luaL_loadbuffer(L, main_src, main_len, "=git2html") != LUA_OK) {
        return report(L, LUA_ERRSYNTAX);
    }
    for (int i = 1; i < argc; i++) {
        lua_pushstring(L, argv[i]);
    }
    return report(L, lua_pcall(L, argc - 1, 0, 0));
}
